000483' when '11' then 'C1030935001347' when '12' then 'C1031011000340' when '13' then 'C1080211000028' when '14' then 'C1030744001296' when '15' then 'C1030644003515' when '16' then 'C1040311005293' when '17' then 'C1091231000013' when '18' then 'C1211252000022' when '19' then 'C1092133000016' when '20' then 'C1031633000292' when '21' then 'C1080434000027' when '22' then 'C1131244000017' when '23' then 'C1087615000019' when '24' then 'C1031537000877' when '25' then 'C1092033000015' when '26' then 'C1086932000011' when '27' then 'C1086832000010' else null end) IN_DEP_CODE, (case OUT_DEP_CTRY when null then '' else substr(OUT_DEP_CTRY,1,3) end) OUT_DEP_CTRY, case when length(OUT_DEP_NAME)>120 then substr(OUT_DEP_NAME,0,120) else OUT_DEP_NAME end OUT_DEP_NAME, VDATE, MDATE, null ACCOUNT_ID, (case IS_CONSTRACTE when '01' then '1' else '2' end) IS_CONSTRACTE, (case TRANSFER_TYPE when '01' then '1' when '99' then '2' else '' end) TRANSFER_TYPE, (case cbc.IS_FIN_SUB_COMPANY when '01' then '2' else '1' end) IDENTI_FLAG, NOW() STATUS_DATE, (case info.CASH_MANA_CATE when '01' then '1' else '2' end) IS_MARKET_FUND, info.STATUS, info.CREATE_USER, info.UPDATE_USER, info.ORG_CODE, cbc.ORG_CODE CREATE_DEPT, info.DEPT_CODE CREATE_DEPT, (case when instr(info.PRD_SPEC_PROPERTY,'02')>0 or instr(info.PRD_SPEC_PROPERTY,'03')>0 then '1' else '2' end ) CROSS_BORDER_FLAG, (case info.ZJXT_FLAG when '01' then '1' else '2' end) ZJXT_FLAG from chb_prd_baseinfo info
left join CHB_ORG_REGIST_BANK_CODE cbc on cbc.REGIST_BANK_CODE=info.ISSUE_PARTY_ID and CBC.STATUS='E' left join sys_datadict_list sdl on info.IN_DEP_NAME = sdl.item_code and sdl.dict_code = 'SVR_IN_DEP_NAME' left join sys_institution sysi on sysi.institution_name = sdl.item_value left join CHB_ORG_REGIST_BANK_CODE cbc2 on sysi.institution_code= cbc2.org_code /****add by leipeng 人行产品基本信息，人行产品代码一旦生成，修改基本信息数据在重新跑批也不会改变了 start**/ LEFT JOIN ( select ifnull(DEAL.FPROD_ID,DEAL.PROD_ID) PROD_ID, max(UPDATE_TIME) UPDATE_TIME,max(CREATE_TIME) CREATE_TIME from CHB_PRD_DEAL DEAL where trade_type = '01' and status IN ('E','M') group by ifnull(DEAL.FPROD_ID,DEAL.PROD_ID)
