update PBC_SEND_ZIP_DAT_FILE F set
ZIP_SEND_STATUS = #{updateStatus,jdbcType=CHAR},
SUBMIT_TIME = now(),
RETURN_ZIP_SEND_STATUS = #{returnStatus,jdbcType=CHAR},
DAT_ZIP_STATUS = #{zipStatus,jdbcType=CHAR}
WHERE NOT EXISTS(
SELECT 1 FROM PBC_PRD_BASEINFO_SUB_DAT SD WHERE F.DAT_ZIP_CODE = SD.DAT_ZIP_CODE AND SD.SEND_STATUS = #{sendStatus,jdbcType=CHAR}
UNION ALL
SELECT 1 FROM PBC_PRD_BASEINFO_END_SUB_DAT SD WHERE F.DAT_ZIP_CODE = SD.DAT_ZIP_CODE AND SD.SEND_STATUS = #{sendStatus,jdbcType=CHAR}
)
AND F.DAT_ZIP_TYPE = 'PI'
